/* Persistent online events: public and admin screens */
#bpEventBtn{background:linear-gradient(#ffbd63,#ef845b);box-shadow:0 4px 0 #b55b36}
#bpEventModal{position:fixed;inset:0;z-index:5400;display:none;align-items:center;justify-content:center;padding:12px;background:rgba(14,25,55,.82);backdrop-filter:blur(5px)}
#bpEventModal.show{display:flex}
.bpEventSheet{width:min(96vw,570px);max-height:90vh;overflow:auto;padding:17px;background:linear-gradient(160deg,#fffefa,#edf5ff);border-radius:22px;box-shadow:0 24px 70px #0006;color:#263750}
.bpEventSheet h2{font-size:21px;margin:2px 0}
.bpEventCard{background:white;border-radius:14px;border:1px solid #d6e0f6;padding:12px;margin:9px 0;box-shadow:0 3px 10px #2342a111}
.bpEventCard strong{font-size:15px;display:block}
.bpEventCard p{font-size:12px;color:#526b88;line-height:1.6;margin:6px 0}
.bpEventActions{display:flex;gap:8px;flex-wrap:wrap;margin:9px 0 0}
.bpEventActions button{border:0;border-radius:9px;color:white;background:linear-gradient(#6ba6ef,#507ad5);box-shadow:0 3px 0 #365d9b;font-size:12px;padding:9px 11px}
.bpEventActions button:disabled{opacity:.55}
.bpEventRanking{font-size:12px;padding:7px 9px;border-radius:9px;background:#f0f5ff;display:grid;gap:3px}
#bpEventStatus,#bpAdminEventStatus{background:#e8f2ff;border-radius:10px;padding:9px;font-size:12px;font-weight:750;line-height:1.5;margin:10px 0}
#bpEventList{max-height:62vh;overflow:auto}
#bpEventBonusLabel:empty{display:none}
#bpEventBonusLabel{display:block;line-height:1.5;font-size:12px;font-weight:900;color:#af641e;padding:3px 8px;text-align:center}
#bpEventForm{background:#fff8e9;border-radius:12px;padding:10px;border:1px solid #f8dda6}
#bpEventForm [hidden]{display:none!important}
#bpEventForm label{margin:7px 0;display:block;font-size:12px}
#bpEventForm input,#bpEventForm select{min-width:0;width:100%;padding:9px 8px;font-size:13px}
#bpEventForm .bpEventDateRow{display:grid;grid-template-columns:1fr 1fr;gap:9px}
#bpEventForm .bpEventActions{margin-top:12px}
#bpEventForm button{font-size:12px}

// Block Pop! ONLINE v1.5.0: persistent server events, coins, tournament and gifts.
const bpEventModal=document.getElementById('bpEventModal');
const bpEventNotice=document.getElementById('bpEventStatus');
const bpEventList=document.getElementById('bpEventList');
const bpAdminEventList=document.getElementById('bpAdminEventList');
const bpAdminEventStatus=document.getElementById('bpAdminEventStatus');
let bpAllEvents=[],bpEventClockOffset=0,bpCoinRate=1,bpActiveCoinUntil=0,bpAdminEvents=[],bpEventBusy=false;
const BP_EVENT_LEDGER='blockpop_event_claims_v1';
function bpEventDate(d){try{return new Date(d).toLocaleString('ja-JP',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}catch{return d}}
function bpEventNow(){return Date.now()+bpEventClockOffset;}
function bpCoinMultiplier(){return bpEventNow()<bpActiveCoinUntil?bpCoinRate:1;}
function bpEventSetMsg(msg){bpEventNotice.textContent=msg;}
function bpEventLoggedClaim(id){try{return !!JSON.parse(localStorage.getItem(BP_EVENT_LEDGER)||'{}')[id]}catch{return false}}
function bpMarkEventClaim(id){try{const data=JSON.parse(localStorage.getItem(BP_EVENT_LEDGER)||'{}');data[id]=true;localStorage.setItem(BP_EVENT_LEDGER,JSON.stringify(data))}catch{}}
async function bpEventRequest(route,body,admin=false){
 const ctl=new AbortController(),tm=setTimeout(()=>ctl.abort(),16000);
 try{
  const response=await fetch(ONLINE_ORIGIN+route,{method:body?'POST':'GET',cache:'no-store',mode:'cors',signal:ctl.signal,
   headers:{...(body?{'Content-Type':'application/json'}:{}),...(admin&&adminBearer?{'Authorization':'Bearer '+adminBearer}:{})},
   ...(body?{body:JSON.stringify(body)}:{})});
  const raw=await response.text();let data;try{data=JSON.parse(raw)}catch{data={}}
  if(!response.ok)throw Error(data.error||'HTTP '+response.status);
  if(!data.ok)throw Error(data.error||'イベントの処理に失敗しました');return data;
 }catch(e){if(e?.name==='AbortError')throw Error('イベントサーバーから返事がないよ');throw e}
 finally{clearTimeout(tm)}
}
function bpEventTypeLabel(e){return e.type==='coins'?'🪙 コイン'+e.multiplier+'倍':e.type==='tournament'?'🏆 スコア大会':'🎁 全員プレゼント'}
function bpEventStatusLabel(status){return {scheduled:'📅 開催予定',active:'🟢 開催中',ended:'🏁 終了',cancelled:'⛔ 中止'}[status]||status}
function bpEventCard(e){
 const card=document.createElement('article');card.className='bpEventCard';
 const heading=document.createElement('strong');heading.textContent=bpEventStatusLabel(e.status)+' '+e.title;
 const kind=document.createElement('p');kind.textContent=bpEventTypeLabel(e);
 const dates=document.createElement('p');dates.textContent='📅 '+bpEventDate(e.startsAt)+' ～ '+bpEventDate(e.endsAt);
 const stats=document.createElement('p');stats.textContent='👥 参加 '+e.participants+'人'+(e.type==='gift'?' / 受取 '+e.claims+'人':'')+(e.rewardCoins?' / 報酬 🪙'+e.rewardCoins:'');
 card.append(heading,kind,dates,stats);
 if(e.type==='tournament'){
  const leaderboard=document.createElement('div');leaderboard.className='bpEventRanking';
  if(!e.leaderboard?.length)leaderboard.textContent='🏆 まだスコアが登録されていないよ';
  else e.leaderboard.forEach((p,i)=>{const div=document.createElement('div');div.textContent=(i+1)+'位 '+p.name+'：'+p.score+'点';leaderboard.appendChild(div)});
  card.appendChild(leaderboard);
  const tip=document.createElement('p');tip.textContent='※ 参加後に「🤝 共有対戦」で対戦すると、サーバーが計算した得点をランキングに登録するよ。';card.appendChild(tip);
 }
 const actions=document.createElement('div');actions.className='bpEventActions';
 if(e.status==='active'){
  const join=document.createElement('button');join.textContent='🙋 イベントに参加';join.addEventListener('click',()=>bpJoinEvent(e.id));actions.appendChild(join);
 }
 if((e.type==='gift'&&e.status==='active'||e.type==='tournament'&&e.status==='ended')&&e.rewardCoins>0){
  const claim=document.createElement('button');claim.textContent=bpEventLoggedClaim(e.id)?'✅ この端末で受取済み':'🎁 報酬を受け取る';claim.disabled=bpEventLoggedClaim(e.id);claim.addEventListener('click',()=>bpClaimEvent(e.id));actions.appendChild(claim);
 }
 card.appendChild(actions);return card;
}
function bpRenderEvents(){
 bpEventList.replaceChildren();
 if(!bpAllEvents.length){bpEventList.textContent='📭 現在公開されているイベントはないよ';return}
 for(const e of bpAllEvents)bpEventList.appendChild(bpEventCard(e));
}
function bpUpdateCoinBonus(){
 const now=bpEventNow(),active=bpAllEvents.filter(x=>x.status==='active'&&x.type==='coins'&&Date.parse(x.startsAt)<=now&&now<Date.parse(x.endsAt));
 active.sort((a,b)=>b.multiplier-a.multiplier);
 const chosen=active[0];bpCoinRate=chosen?Number(chosen.multiplier):1;bpActiveCoinUntil=chosen?Date.parse(chosen.endsAt):0;
 const label=document.getElementById('bpEventBonusLabel');if(label)label.textContent=chosen?'🎪 '+chosen.title+' 🪙'+bpCoinRate+'倍！':'';
}
async function bpFetchEvents(silent=false){
 try{
  const data=await bpEventRequest('/api/events');
  bpAllEvents=data.events||[];if(data.serverTime)bpEventClockOffset=Date.parse(data.serverTime)-Date.now();
  bpUpdateCoinBonus();bpRenderEvents();if(!silent)bpEventSetMsg('✅ イベント情報を更新したよ');
  // Coin bonus is automatic for all active players; record a single participant.
  const active=bpAllEvents.filter(e=>e.type==='coins'&&e.status==='active');
  const id=playerRandomId();if(id)for(const event of active){
   const key='blockpop_event_joined_'+event.id;
   if(localStorage.getItem(key))continue;
   bpEventRequest('/api/events/join',{id:event.id,playerId:id,nickname:bpEventPlayerName()}).then(()=>localStorage.setItem(key,'1')).catch(()=>{});
  }
 }catch(e){if(!silent)bpEventSetMsg('⚠️ '+e.message)}
}
function bpEventPlayerName(){return (typeof accountNickname==='string'&&accountSession?accountNickname:document.getElementById('bpGuestName')?.value||'ゲスト').slice(0,16)}
async function bpJoinEvent(id){
 if(bpEventBusy)return;const playerId=playerRandomId();if(!playerId){bpEventSetMsg('端末のプレイヤーIDを作れなかったよ');return}
 bpEventBusy=true;bpEventSetMsg('📡 参加を登録中…');
 try{await bpEventRequest('/api/events/join',{id,playerId,nickname:bpEventPlayerName()});
  try{localStorage.setItem('blockpop_event_joined_'+id,'1')}catch{}
  bpEventSetMsg('✅ 参加完了！ '+(bpAllEvents.find(e=>e.id===id)?.type==='tournament'?'共有盤面対戦で記録を作ろう！':'イベントを楽しんでね！'));
  await bpFetchEvents(true);
 }catch(e){bpEventSetMsg('⚠️ '+e.message)}finally{bpEventBusy=false}
}
async function bpClaimEvent(id){
 if(bpEventBusy||bpEventLoggedClaim(id))return;const playerId=playerRandomId();if(!playerId)return;
 bpEventBusy=true;bpEventSetMsg('🎁 サーバーで受取を確認中…');
 try{const data=await bpEventRequest('/api/events/claim',{id,playerId,nickname:bpEventPlayerName()});
  if(data.already){bpEventSetMsg('✅ このイベントの報酬は受取済みだよ');return}
  if(data.coins>0&&!bpEventLoggedClaim(id)){bpMarkEventClaim(id);coins+=data.coins;saveCoins();renderShop();bpEventSetMsg('🎉 🪙'+data.coins+'コインを受け取ったよ！');}
  await bpFetchEvents(true);
 }catch(e){bpEventSetMsg('⚠️ '+e.message)}finally{bpEventBusy=false}
}
function bpTimeInput(d){const dt=new Date(d);if(!Number.isFinite(dt.getTime()))return '';const local=new Date(dt.getTime()-dt.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function bpEventClearForm(){
 document.getElementById('bpEventId').value='';document.getElementById('bpEventTitle').value='';
 document.getElementById('bpEventType').value='coins';
 document.getElementById('bpEventStart').value=bpTimeInput(Date.now()+3600000);
 document.getElementById('bpEventEnd').value=bpTimeInput(Date.now()+25*3600000);
 document.getElementById('bpEventMult').value='2';document.getElementById('bpEventReward').value='0';
 document.getElementById('bpEventSave').textContent='💾 イベントを作成';bpEventSyncForm();
}
function bpEventSyncForm(){
 const type=document.getElementById('bpEventType').value;
 document.getElementById('bpEventCoinLine').hidden=type!=='coins';
 document.getElementById('bpEventRewardLine').hidden=type==='coins';
}
function bpEventEditForm(e){
 document.getElementById('bpEventId').value=e.id;document.getElementById('bpEventTitle').value=e.title;
 document.getElementById('bpEventType').value=e.type;document.getElementById('bpEventStart').value=bpTimeInput(e.startsAt);
 document.getElementById('bpEventEnd').value=bpTimeInput(e.endsAt);document.getElementById('bpEventMult').value=String(e.multiplier);
 document.getElementById('bpEventReward').value=String(e.rewardCoins);
 document.getElementById('bpEventSave').textContent='💾 イベントを編集';bpEventSyncForm();
 document.getElementById('bpEventTitle').focus();
}
function bpRenderAdminEvents(){
 bpAdminEventList.replaceChildren();if(!bpAdminEvents.length){bpAdminEventList.textContent='登録イベントがないよ';return;}
 for(const e of bpAdminEvents){
  const card=document.createElement('div');card.className='bpEventCard';
  const h=document.createElement('strong');h.textContent=bpEventStatusLabel(e.status)+' '+e.title;
  const info=document.createElement('p');info.textContent=bpEventTypeLabel(e)+' / 👥'+e.participants+'人 / 🎁'+e.claims+'人';
  const actions=document.createElement('div');actions.className='bpEventActions';
  const edit=document.createElement('button');edit.textContent='✏️ 編集';edit.disabled=e.status==='cancelled';edit.addEventListener('click',()=>bpEventEditForm(e));
  const cancel=document.createElement('button');cancel.textContent='⛔ 中止';cancel.disabled=e.status==='cancelled';
  cancel.addEventListener('click',async()=>{if(!confirm('「'+e.title+'」を中止する？参加記録は残るよ。'))return;
   await bpEventAdminSave({action:'cancel',id:e.id},'中止したよ')});actions.append(edit,cancel);card.append(h,info,actions);bpAdminEventList.appendChild(card);
 }
}
async function bpRefreshAdminEvents(){
 if(!adminBearer)return;
 try{const d=await bpEventRequest('/api/events/admin',null,true);bpAdminEvents=d.events||[];bpRenderAdminEvents();bpAdminEventStatus.textContent='✅ 登録イベント '+bpAdminEvents.length+'件（サーバー保存）'}
 catch(e){bpAdminEventStatus.textContent='⚠️ '+e.message}
}
async function bpEventAdminSave(body,msg){
 if(!adminBearer){bpAdminEventStatus.textContent='管理者ログインが必要だよ';return}
 bpAdminEventStatus.textContent='📡 サーバーへ保存中…';
 try{await bpEventRequest('/api/events/admin',body,true);bpAdminEventStatus.textContent='✅ '+msg;bpEventClearForm();await bpRefreshAdminEvents();await bpFetchEvents(true)}
 catch(e){bpAdminEventStatus.textContent='⚠️ '+e.message}
}
document.getElementById('bpEventBtn').addEventListener('click',()=>{bpEventModal.classList.add('show');bpFetchEvents()});
document.getElementById('bpEventClose').addEventListener('click',()=>bpEventModal.classList.remove('show'));
document.getElementById('bpEventRefresh').addEventListener('click',()=>bpFetchEvents());
document.getElementById('bpEventType').addEventListener('change',bpEventSyncForm);
document.getElementById('bpEventClear').addEventListener('click',bpEventClearForm);
document.getElementById('bpEventReloadAdmin').addEventListener('click',bpRefreshAdminEvents);
document.getElementById('bpEventSave').addEventListener('click',()=>{
 const start=document.getElementById('bpEventStart').value,end=document.getElementById('bpEventEnd').value;
 if(!start||!end||Date.parse(start)>=Date.parse(end)){bpAdminEventStatus.textContent='⚠️ 開始より後に終了を設定してね';return}
 const id=document.getElementById('bpEventId').value,type=document.getElementById('bpEventType').value;
 const body={action:id?'edit':'create',id,title:document.getElementById('bpEventTitle').value.trim(),type,
  startsAt:new Date(start).toISOString(),endsAt:new Date(end).toISOString(),multiplier:type==='coins'?Number(document.getElementById('bpEventMult').value):1,
  rewardCoins:type==='coins'?0:Number(document.getElementById('bpEventReward').value)};
 bpEventAdminSave(body,id?'イベントを編集したよ':'イベントを公開したよ');
});
bpEventClearForm();
setTimeout(()=>bpFetchEvents(true),3600);
setInterval(()=>{if(document.visibilityState!=='hidden')bpFetchEvents(true)},65000);

